size_t RegisterMPCImage(void) {
    MagickInfo
        *magick_info;

    magick_info = (MagickInfo *) AcquireMagickMemory(sizeof(MagickInfo));
    (void) memset(magick_info, 0, sizeof(MagickInfo));
    magick_info->signature = MagickSignature;
    magick_info->format = (const char **) AcquireMagickMemory(2 * sizeof(char *));
    magick_info->format[0] = ConstantString("MPC");
    magick_info->format[1] = (char *) NULL;
    magick_info->description = ConstantString("Magick Persistent Cache");
    magick_info->module = ConstantString("MPC");
    magick_info->seekable = MagickTrue;
    magick_info->stealth = MagickTrue;
    magick_info->decoder = (DecodeImageHandler *) ReadMPCImage;
    magick_info->encoder = (EncodeImageHandler *) WriteMPCImage;
    (void) RegisterMagickInfo(magick_info);
    return sizeof(MagickInfo);
}

